// L'allegato che in questa RFQ porta le proposte di un contenuto. Lo stesso file arrivato due volte
// nella stessa RFQ propone una volta sola: due serie di nodi uguali sarebbero doppio lavoro e doppio
// conteggio nel gate.
func (q *Queries) PortatoreDelFile(ctx context.Context, arg PortatoreDelFileParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, portatoreDelFile, arg.ThreadID, arg.Sha256)
	var allegato_id uuid.UUID
	err := row.Scan(&allegato_id)
	return allegato_id, err
}

